// Generated by the main.cpp module split: the code below is a verbatim
// slice of the original single-translation-unit firmware/src/main.cpp.

#include "yat_beep.h"

#include <Arduino.h>

#include "yat_config.h"
#include "yat_common.h"

// The board really does have a buzzer (GPIO45): both e1002-test/src/selftest
// (bootMelody) and voicedemo drive it with plain Arduino tone(), which routes
// through LEDC and — given a duration — stops itself, so beep() only has to
// wait it out. No LED-only fallback is needed; the LED is used *as well*,
// held on for the duration of the capture (see voiceRecordInto).
void beep(uint16_t freq, uint16_t ms) {
  tone(PIN_BUZZER, freq, ms);
  delay(ms + 10);
}

// The device's whole audible vocabulary, kept in one place so the cues stay
// distinguishable from each other (README documents what each means to the
// user). PRD §4.4's four voice cues came first; the rest answer presses and
// outcomes that would otherwise be silent or, worse, share a sound with
// something they do not mean. The rule the additions follow: a fault buzzes
// low, everything else stays in the pleasant register, and no two cues that
// can follow the same action sound alike.
//
// config.json's "beep": false (DeviceConfig::beep, mirrored in g_beepEnabled)
// silences exactly the four cues that are pure acknowledgement — a press
// answered, a card asked for, a boot survived. The household that turns them
// off is asking for a quiet shelf device, not a mute one, so everything that
// carries information a person is standing there waiting for stays audible at
// any setting:
//
//   muted by "beep": false — page-step ack (beepPageStep, which is also the
//     help-card ack), the no-key double-chirp (beepNoKey), the cold-boot chirp
//     (setup(), which reads the NVS mirror because it fires before the config
//     is even mounted), and the new-error awareness beep (beepNewError, see
//     maybeBeepNewError — the household turning cues off gets a quiet shelf
//     device, including one that no longer buzzes about a fault it can still
//     read about in YAT ERRORS or the phone portal's issues card). That last
//     one carries a second, narrower silence no other cue here has: quiet
//     hours, because it is the only one of these that can fire on an
//     unattended timer wake rather than a press or a boot someone is standing
//     in front of;
//   never muted — the voice cues (record start/stop, match, no-match, held for
//     later, error), beepHoldConfirmed (「聽見嘀一聲先放手」 is a documented
//     instruction: without it nobody knows when to let go of the button), and
//     beepEnterSetup (the only sign of life through the ~30 s refresh that
//     draws the setup screen).
void beepRecordStart() { beep(1319, 80); }             // high chirp: speak now
void beepRecordStop() { beep(880, 80); }               // lower chirp: heard you, working
void beepMatch() { beep(1047, 80); beep(1319, 120); }  // rising double: switching page
void beepError() { beep(330, 300); }                   // low buzz: something is wrong
// "I heard you, I just didn't recognise it" — the one voice outcome that is
// not a fault and that the user can fix on the spot by saying it again. It
// used to share beepError's 330 Hz/300 ms buzz with an expired STT key, a dead
// mic and a dropped network, which made a normal misrecognition sound like
// broken hardware and gave the three real faults no distinguishing sound at
// all. Falling, soft, and short: "not that one, try again".
void beepNoMatch() { beep(880, 90); beep(698, 120); }  // gentle falling double: try again
// A voice command matched, but a warning takeover owns the panel until the
// signal drops, so this page cannot appear now — beepMatch's rising "switching
// page" would promise a screen change that is hours away. The choice IS saved
// and shows the moment the takeover clears, so this acknowledges rather than
// refuses: two level tones, "noted, holding".
void beepHeldForLater() { beep(1047, 90); beep(1047, 150); }  // level double: saved, not now
// docs/UX-NONTECH.md §6-§8, fix 6: a KEY0 tap with no STT key configured is
// not a fault — it's the most prominent button on a fresh-out-of-the-box
// device doing exactly what it was told (nothing is set up yet). beepError's
// angry 330 Hz/300 ms buzz reads as broken; two short mid tones read as
// "noted" instead. beepError is left to the genuine faults — an expired or
// rejected STT key, a mic that will not start, a network that is down — with
// a misrecognition split off into beepNoMatch above.
void beepNoKey() {
  if (!g_beepEnabled) return;  // acknowledgement only — mutable, see the block above
  beep(659, 60);
  beep(659, 60);
}  // soft neutral double-chirp
// Entering WiFi provisioning (first boot after a flash, a KEY0 5 s hold, or 3
// failed connects). A friendly rising 3-tone played the instant we enter setup
// mode — the only audible sign the device is alive during the ~30 s blocking
// e-paper refresh that draws the setup-QR screen, which otherwise leaves a
// just-flashed panel showing its old frozen image with no feedback at all.
void beepEnterSetup() { beep(880, 110); beep(1175, 110); beep(1568, 180); }  // rising: setup mode
// Fired the moment a KEY0 hold crosses the 5 s provisioning threshold, while
// the button is still down — tells the user "held long enough, let go now"
// instead of nothing until the screen redraws seconds later.
void beepHoldConfirmed() { beep(1568, 260); }  // one firm tone at the 5 s mark
// A page button pressed either while the device is awake (button-latch
// sections, yat_buttons.cpp's keyStepPage()/processKeyLatches()) or, the more
// common case, as the very press that woke it (main.cpp's KEY1/KEY2 handling
// and the both-arrows help card, right after the page count is known).
// Nothing is being recorded, nothing failed and no mode changed, so it is
// deliberately unlike every cue around it: one short mid tone whose only job
// is "that press counted, the next page is coming". It fires the instant the
// press is noticed, which on the 30 s refresh path is up to half a minute
// before the screen can possibly show the result. A wake-time help request
// deferred to the NEXT cycle (requestHelpNextCycle/takeHelpRequest) does not
// beep again when that cycle draws the card — the awake press that asked for
// it was already acknowledged the moment it latched.
void beepPageStep() {
  if (!g_beepEnabled) return;  // acknowledgement only — mutable, see the block above
  beep(988, 70);
}  // single short mid tone: page stepped
// A NEW fault landed this wake (see maybeBeepNewError) — the one cue in this
// file meant to be heard with nobody standing in front of the device. Lower
// than beepError's already-low 330 Hz, and two flat pulses rather than one
// longer tone, so a household that has learned "one buzz mid-voice-command
// means the mic/network broke" does not mistake this for that: this is
// "something happened while you were away, go look", not "your command just
// failed". Not muted by g_beepEnabled here — maybeBeepNewError checks that
// itself, alongside quiet hours, before ever calling this.
void beepNewError() { beep(220, 220); beep(220, 220); }  // two low buzzes: check YAT ERRORS or the phone portal
// A firmware update finished installing (yat_ota.cpp) and the device is about
// to reboot into it. Never muted, for the same reason beepEnterSetup is not:
// somebody is standing in front of the device watching a progress bar, and
// what follows is a reboot and a ~30 s refresh during which the panel and the
// phone both go quiet. Without this, a successful update and a device that has
// just died are the same experience. Pitched above beepHoldConfirmed's single
// 1568 Hz tone and rising through it, so it cannot be mistaken for the "you
// can let go of the button now" cue that shares the same register.
void beepUpdateDone() { beep(1568, 200); beep(1976, 280); }  // rising pair: update installed, rebooting
